$personal=Yii::$app->user->identity->role==='teacher';$this->title=$personal?'Shaxsiy KPI paneli':'Boshqaruv paneli · KPI';$c=array_column($counts,'n','status');$total=(int)array_sum($c);$approved=(int)($c['approved']??0);$pending=(int)($c['submitted']??0)+(int)($c['review']??0);$ratio=$total?(int)round($approved/$total*100):0;
